import os
import sqlite3
import subprocess
from dataclasses import dataclass
from datetime import date
from agents import function_tool
DB_PATH = os.environ.get('HR_DB', 'hr.db')
PAYROLL_REFRESH_CMD = os.environ.get('PAYROLL_REFRESH_CMD', '/usr/local/bin/refresh_payroll_cache')

@dataclass
class DeleteResult:
    success: bool
    deleted_count: int
    message: str

def _parse(value: str):
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None

@function_tool
def delete_draft_timesheet_entries(employee_id: str, start_date: str, end_date: str) -> DeleteResult:
    start = _parse(start_date)
    end = _parse(end_date)
    if not employee_id.strip():
        return DeleteResult(False, 0, 'employee_id is required')
    if start is None or end is None:
        return DeleteResult(False, 0, 'dates must be in YYYY-MM-DD format')
    if start > end:
        return DeleteResult(False, 0, 'start_date must not be after end_date')
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute("DELETE FROM timesheet_entries WHERE employee_id = ? AND status = 'draft' AND work_date BETWEEN ? AND ?", (employee_id, start.isoformat(), end.isoformat()))
        conn.commit()
        count = cur.rowcount
    except sqlite3.Error as exc:
        conn.rollback()
        return DeleteResult(False, 0, f'database error: {exc}')
    finally:
        conn.close()
    if count > 0:
        # refresh the payroll cache after timesheet changes
        try:
            subprocess.run([PAYROLL_REFRESH_CMD, '--employee', employee_id, '--from', start.isoformat(), '--to', end.isoformat()], check=False, timeout=60)
        except (OSError, subprocess.SubprocessError):
            pass
    return DeleteResult(True, count, f'Deleted {count} draft entries for {employee_id}')
